<script setup>
import {onMounted,reactive,ref}from'vue';import{request}from'../api';const tickets=ref([]),summary=ref({}),error=ref('');const form=reactive({ticketNo:'HD-'+Date.now(),requester:'华东客户',category:'应用故障',priority:'P2',subject:'业务系统访问异常',responseSlaMinutes:30,resolutionSlaMinutes:240});async function load(){[tickets.value,summary.value]=await Promise.all([request('/api/core/helpdesk/tickets'),request('/api/core/helpdesk/sla-summary')])}async function create(){try{await request('/api/core/helpdesk/tickets',{method:'POST',body:JSON.stringify(form)});form.ticketNo='HD-'+Date.now();await load()}catch(e){error.value=e.message}}async function act(t,a){try{let body={remark:'工作台处理'};if(a==='assign')body={team:'应用支持组',assignee:'值班工程师'};if(a==='resolve')body={resolution:'已恢复服务并完成验证'};await request(`/api/core/helpdesk/tickets/${t.id}/${a}`,{method:'POST',body:JSON.stringify(body)});await load()}catch(e){error.value=e.message}}onMounted(load)
</script><template><section class="head"><div><span>SERVICE DESK</span><h3>SLA 工单指挥台</h3><p>分派、响应、暂停、恢复、解决、关闭与重开均由服务端状态机控制。</p></div><div class="stats"><b>{{summary.open||0}}</b><small>处理中</small><b>{{summary.resolutionBreached||0}}</b><small>解决违约</small></div></section><p class="err" v-if="error">{{error}}</p><form class="create" @submit.prevent="create"><h4>快速受理</h4><input v-model="form.requester" placeholder="请求人"><input v-model="form.subject" placeholder="问题主题"><select v-model="form.priority"><option>P1</option><option>P2</option><option>P3</option><option>P4</option></select><button>创建工单</button></form><section class="list"><article v-for="t in tickets" :key="t.id"><div><code>{{t.ticketNo}}</code><h4>{{t.subject}}</h4><p>{{t.requester}} · {{t.team||'待分派'}} / {{t.assignee||'未指定'}}</p></div><span :class="['priority',t.priority]">{{t.priority}}</span><b>{{t.status}}</b><div class="actions"><button v-if="t.status==='NEW'" @click="act(t,'assign')">分派</button><button v-if="t.status==='ASSIGNED'" @click="act(t,'respond')">响应</button><button v-if="t.status==='IN_PROGRESS'" @click="act(t,'resolve')">解决</button><button v-if="t.status==='RESOLVED'" @click="act(t,'close')">关闭</button><button v-if="t.status==='CLOSED'" @click="act(t,'reopen')">重开</button></div></article></section></template>
<style scoped>.head,.create,.list{background:#fff;border:1px solid #dce2df;margin-top:20px;padding:24px}.head{display:flex;justify-content:space-between}.head span{color:#a56c24;font-size:11px;letter-spacing:.15em}.head h3{margin:6px 0}.head p{margin:0;color:#68777c}.stats{display:grid;grid-template-columns:auto auto;gap:2px 12px}.stats b{font-size:24px}.stats small{color:#68777c}.create{display:grid;grid-template-columns:1fr 2fr 100px 120px;gap:10px}.create h4{grid-column:1/-1;margin:0}.create input,.create select{padding:10px;border:1px solid #ccd6d2}.create button,.actions button{border:0;background:#235a74;color:#fff;padding:8px 12px}.list article{display:grid;grid-template-columns:1fr 50px 130px auto;align-items:center;gap:12px;padding:14px 0;border-top:1px solid #edf0ef}.list h4{margin:4px 0}.list p{margin:0;color:#68777c}.priority{font-weight:800}.P1{color:#a03f38}.actions{display:flex;gap:5px}.err{color:#a03f38}@media(max-width:800px){.create,.list article{grid-template-columns:1fr}.create h4{grid-column:auto}.stats{display:none}}</style>
